from pathlib import Path

root=Path.cwd()

def rep(path, old, new):
 p=root/path; s=p.read_text(); assert s.count(old)==1,(path,s.count(old),old[:80]); p.write_text(s.replace(old,new))

rep('apps/server/src/services/task/index.ts', "import { collapseActivityLog } from './collapseActivityLog';", "import { collapseActivityLog } from './collapseActivityLog';\nimport { buildInterruptedTaskGeneration } from './interruptedGeneration';")
