# Make the real-SWR regression prove dedupe across the whole idle cadence.
rep('src/store/task/slices/detail/polling.test.tsx', '''    await act(async () => {\n      await vi.advanceTimersByTimeAsync(50);\n    });\n    expect(taskService.getDetail).toHaveBeenCalledTimes(1);\n    await act(async () => {\n      await vi.advanceTimersByTimeAsync(15_000);\n    });''', '''    await act(async () => {\n      await vi.advanceTimersByTimeAsync(50);\n    });\n    expect(taskService.getDetail).toHaveBeenCalledTimes(1);\n    // A second subscriber arriving anywhere inside the 15s idle cadence must\n    // share the existing request/cache rather than create another transport.\n    await act(async () => {\n      await vi.advanceTimersByTimeAsync(5_000);\n    });\n    expect(taskService.getDetail).toHaveBeenCalledTimes(1);\n    await act(async () => {\n      await vi.advanceTimersByTimeAsync(10_000);\n    });''')
